/**2022-12-19 PAYMENT TRANSACTION ATTACHMENT TABLE */
CREATE TABLE `T_CK_PAYMENT_TXN_ATT_INVOICE` (
  `PTX_ATT_INV_ID` varchar(35) NOT NULL COMMENT 'JOB ATTACHMENT ID - UUID',
  `PTX_ATT_INV_JOB` varchar(35) NOT NULL COMMENT 'JOB - REFERENCE T_CK_JOB:JOB_ID FF',
  `PTX_ATT_INV_TYPE` varchar(35) NOT NULL COMMENT 'JOB ATTACHMENT TYPE - REFERENCE T_CK_MST_INVOICE_TYPE:INVT_ID',
  `PTX_ATT_INV_NAME` varchar(256) DEFAULT NULL COMMENT 'JOB ATTACHMENT NAME',
  `PTX_ATT_INV_LOC` varchar(1024) DEFAULT NULL COMMENT 'JOB ATTACHMENT PATH REFERENCE FROM SYS_PARAM SETUP',
  `PTX_ATT_INV_STATUS` char(1) DEFAULT NULL COMMENT 'JOB ATTACHMENT STATUS - A : I ',
  `PTX_ATT_INV_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `PTX_ATT_INV_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `PTX_ATT_INV_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `PTX_ATT_INV_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`PTX_ATT_INV_ID`),
  KEY `FK_CK_PAYMENT_TXN_T_CK_MST_INVOICE_TYPE` (`PTX_ATT_INV_TYPE`),
  KEY `FK_CK_JPAYMENT_TXN_ATT_INVOICE` (`PTX_ATT_INV_JOB`),
  CONSTRAINT `FK_CK_JPAYMENT_TXN_ATT_INVOICE` FOREIGN KEY (`PTX_ATT_INV_JOB`) REFERENCES `T_CK_JOB` (`JOB_ID`),
  CONSTRAINT `FK_CK_PAYMENT_TXN_T_CK_MST_INVOICE_TYPE` FOREIGN KEY (`PTX_ATT_INV_TYPE`) REFERENCES `T_CK_MST_INVOICE_TYPE` (`INVT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='PAYMENT TRANSACTION INVOICE ATTACHMENT TABLE';

